class mcf_graph_int_cost {
public:
    int n;
    vector<pair<int, int>> pos;
    vector<vector<pair<int, int>>> g;

    struct edge {
        int to;
        int rev;
        int cap;
        int cost;
    };

    mcf_graph_int_cost(int n) : n(n), pos(), g(n) {}

    int add_edge(int from_, int to, int cap, int cost) {
        int m = pos.size();
        pos.push_back(make_pair(from_, g[from_].size()));
        g[from_].push_back({to, g[to].size(), cap, cost});
        g[to].push_back({from_, g[from_].size() - 1, 0, -cost});
        return m;
    }

    edge get_edge(int i) {
        auto _e = g[pos[i].first][pos[i].second];
        auto _re = g[_e.to][_e.rev];
        return {pos[i].first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost};
    }

    vector<edge> edges() {
        vector<edge> ret;
        for (auto p : pos) {
            auto _e = g[p.first][p.second];
            auto _re = g[_e.to][_e.rev];
            ret.push_back({p.first, _e.to, _e.cap + _re.cap, _re.cap, _e.cost});
        }
        return ret;
    }

    bool _dual_ref(int s, int t) {
        vector<int> dist(n, INF);
        vector<int> pv(n, -1);
        vector<int> pe(n, -1);
        vector<bool> vis(n, false);

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> que;
        dist[s] = 0;
        que.push(make_pair(0, s));
        while (!que.empty()) {
            auto v = que.top().second;
            que.pop();
            if (vis[v]) continue;
            vis[v] = true;
            if (v == t) break;
            for (auto e : g[v]) {
                if (vis[e.to] || e.cap == 0) continue;
                int cost = e.cost - dual[e.to] + dual[v];
                if (dist[e.to] > dist[v] + cost) {
                    dist[e.to] = dist[v] + cost;
                    pv[e.to] = v;
                    pe[e.to] = g[v].size() - 1;
                    que.push(make_pair(dist[e.to] << 32 | e.to, e.to));
                }
            }
        }
        if (!vis[t]) return false;

        for (int v = 0; v < n; v++) {
            if (!vis[v]) continue;
            dual[v] -= dist[t] - dist[v];
        }
        return true;
    }

    vector<pair<int, int>> slope(int s, int t, int flow_limit = INF) {
        vector<int> dual(n, 0);
        vector<int> dist(n, INF);
        vector<int> pv(n, -1);
        vector<int> pe(n, -1);
        vector<bool> vis(n, false);

        vector<pair<int, int>> result;
        int flow = 0;
        int cost = 0;
        int prev_cost = -1;
        while (flow < flow_limit) {
            if (!_dual_ref(s, t)) break;
            int c = flow_limit - flow;
            int v = t;
            while (v != s) {
                c = min(c, g[pv[v]][pe[v]].cap);
                v = pv[v];
            }
            v = t;
            while (v != s) {
                auto e = g[pv[v]][pe[v]];
                e.cap -= c;
                g[v][e.rev].cap += c;
                v = pv[v];
            }
            int d = -dual[s];
            flow += c;
            cost += c * d;
            if (prev_cost == d) result.pop_back();
            result.push_back(make_pair(flow, cost));
            prev_cost = cost;
        }
        return result;
    }

    pair<int, int> flow(int s, int t, int flow_limit = INF) {
        return slope(s, t, flow_limit).back();
    }

    void print() {
        for (int i = 0; i < n; i++) {
            cout << "Vertex " << i << " has edges: ";
            for (auto e : g[i]) {
                cout << "(" << e.to << ", " << e.cap << ", " << e.cost << ") ";
            }
            cout << endl;
        }
    }

    void print_edges() {
        for (auto e : edges()) {
            cout << "(" << e.from_ << ", " << e.to << ", " << e.cap << ", " << e.cost << ") ";
        }
        cout << endl;
    }
};

