uint64_t powmod(uint64_t base, uint64_t exponent, uint64_t mod) {
    uint64_t result = 1;
    base %= mod;
    while (exponent > 0) {
        if (exponent % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exponent /= 2;
    }
    return result;
}

